Tool response:
Tool: list_certificants_for_audit_sample
Description: List certificants in an audit sample with their audit status and CEU certificate status
Parameters:
    {
      "type": "object",
      "properties": {
        "audit_sample_id": {
          "type": "integer",
          "minimum": 1,
          "title": "Audit Sample Id",
          "description": ""
        }
      },
      "required": [
        "audit_sample_id"
      ]
    }

Tool response:
Tool: mark_certificant_submitted
Description: Mark a certificant's audit status as Submitted if CEU certificates are on file
Parameters:
    {
      "type": "object",
      "properties": {
        "audit_sample_id": {
          "type": "integer",
          "minimum": 1,
          "title": "Audit Sample Id",
          "description": ""
        },
        "certificant_id": {
          "type": "integer",
          "minimum": 1,
          "title": "Certificant Id",
          "description": ""
        }
      },
      "required": [
        "audit_sample_id",
        "certificant_id"
      ]
    }
